mapper.select:
select participation_fee + fee
from personal_match
where personal_match_id = #{matchId}

mapper.insert:
	INSERT INTO personal_match_participant (
    	user_id, personal_match_id, attendance, status, payment_id, applied_at
	) VALUES (
    	#{userId}, #{matchId}, 0, '결제완료', #{paymentId}, NOW()
	)

mapper.select:
select count(*)
from personal_match_participant
where user_id = #{userId}
and personal_match_id = #{matchId}
and (status is null or status <> '취소')
